head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.key_row = '';
scwin.clickId;
scwin.gIsurCd;
scwin.gMarket = js_market;
scwin.vScrenID = "ULDSTF30340.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_init = function() {
    //업무구분초기화
    dts_business.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=QUES_BZ_TP_CD";
    dts_business.Reset();

    //진행사항 초기화
    dts_progress_state.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=ANS_PROG_STAT_CD";
    dts_progress_state.Reset();

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_EDate.setValue(vCurDate); // 현재날짜

};
scwin.fn_search = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/VocQnA.do?method=listVocQnA";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID);
    if (js_dep_cd.substr(0, 1) == '5') {
        //시장감시부로 변경  2024.05.10
        url += "&QUES_BZ_TP_CD=3"; //지분만 보이기

    } else {
        url += "&QUES_BZ_TP_CD=" + $c.stf.getObjectValue(cmb_business);
    }
    url += "&REPLY_YN=" + $c.stf.getObjectValue(cmb_REPLY_YN);
    url += "&CONTN_TITLE=" + $c.stf.getObjectValue(txb_CONTN_TITLE);
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDate);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDate);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_qnaList.DataID = encodeURI(url);
    dts_qnaList.Reset();
};
scwin.fn_setKey = function(row) {
    scwin.key_row = row;
};
scwin.fn_readDetail = async function(row, colid) {
    if (colid == "QUES_TITLE") {
        if (dts_qnaList.getCellData(row, "ANS_OBJ_CONTN_ID") == '0') {
            await $c.frame.CreateDialogFrame("ULDSTF30341", "/bizspt/ULDSTF30341.gfm", "고객의소리 Q&A 질문", 50, 20, 600, 700 + 30, "window");
        } else {
            await $c.frame.CreateDialogFrame("ULDSTF30342", "/bizspt/ULDSTF30342.gfm", "고객의소리 Q&A 답변", 50, 20, 600, 460 + 30, "window");
        }
    }
};
scwin.fn_setId = function(obj) {
    if (scwin.clickId != "input") {
        scwin.clickId = dts_qnaList.getCellData(eval(obj), "QUES_ID");
    }
};
scwin.fn_getId = function() {
    return scwin.clickId;
};
scwin.dateCheck = function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.img_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.img_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_search();
};
scwin.dts_qnaList_OnFail = function() {
    $c.stf.alert_error(dts_qnaList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_qnaList_OnLoadError = function() {
    $c.stf.alert_error(dts_qnaList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_business_OnLoadCompleted = function(rowcount) {
    for (var i = 1; i <= dts_business.getTotalRow(); i++) {
        if (scwin.gMarket == '1' || scwin.gMarket == '2') {
            if (dts_business.getCellData(i, 1) == '3') {
                //'3' =지분
                $c.cp.removeRow(dts_business, i);
                i--; // 삭제한 경우는 해당하는 위치에서 한번더 검색하게 함.

            }
        }
    }
};
scwin.dts_qnaList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_qnaList.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnClick = function(row, colid) {
    scwin.fn_setKey(row);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.gIsurCd = dts_qnaList.getCellData(row, "ISUR_CD");
    if (colid == 'QUES_TITLE') {
        scwin.fn_readDetail(row, colid);
    } else if (colid == "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    if (js_dep_cd.substr(0, 1) == '5') {
        //시장감시부로 변경 20240510
        $c.stf.showObj(panel_BZ, false);
        $c.stf.showObj(panel_mkt, false);
    }
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (js_market == '1' || js_market == '2' || js_market == '6') {
        $c.stf.showObj(panel_mkt, false);
    }
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    scwin.fn_init();
    scwin.fn_search();
};
